<script setup lang="tsx">
import { ref, computed, onMounted, onBeforeUnmount } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo } from "@/util/tips";
import { PostRejudgeRecently, PostRejudgeSearch, PostRejudgeAll, JudgeStatus, GetJudgeStatusOptions } from "@/apis/judge.ts";
import { GetJudgerManageList, PostJudgerSetting } from "@/apis/judge.ts";
import type { Judger } from "@/types/judge.ts";
import router from "@/router";
import { GetSubmitLanguages, JudgeLanguage } from "@/apis/language.ts";
import type { TNodeReturnValue } from "tdesign-vue-next";
import type { CellParams } from "@/types/table";
import { useBreakpoint } from "@/composables/useBreakpoint";

const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

const searchFormLayout = computed(() => (isMobile.value ? "vertical" : "inline"));

const rejudgeRecentlyLoading = ref(false);
const rejudgeAllLoading = ref(false);

// 判题机管理（前端归一化后 boolean）
interface JudgerRow {
  key: string;
  name: string;
  maxJob: number;
  modifyTimeRaw: number; // 原始毫秒时间戳，无心跳为 0
  enable: boolean;
  hidden: boolean;
  updating: boolean; // 是否正在更新（乐观更新中）
  updatedAt?: number; // 最近一次成功更新的时间戳，用于轮询跳过旧快照
}

const judgerList = ref([] as JudgerRow[]);
const judgerLoading = ref(false);
// 首次加载标志：仅在真正首次加载时显示 loading，避免空列表时轮询反复闪烁
let loadedOnce = false;

// 说明：tdesign 的 BaseTableCol<T> 是递归类型（children?: BaseTableCol<T>[]），本页 cell 返回 JSX，
// 直接标注会触发 TS2589（Type instantiation is excessively deep），故按其字段构造一个非递归的等价列类型
type JudgerColumn = {
  title: string;
  colKey: string;
  width?: string | number;
  cell?: (_h: unknown, data: CellParams<JudgerRow>) => TNodeReturnValue;
};

const judgerColumns: JudgerColumn[] = [
  { title: "标识", colKey: "key", width: 120 },
  { title: "名称", colKey: "name", width: 160 },
  { title: "并发", colKey: "maxJob", width: 80 },
  {
    title: "最近心跳",
    colKey: "modifyTimeRaw",
    width: 220,
    cell: (_h: unknown, data: CellParams<JudgerRow>) => {
      const row = data.row;
      const timeStr = row.modifyTimeRaw ? new Date(row.modifyTimeRaw).toLocaleString() : "-";
      const online = isOnline(row.modifyTimeRaw);
      return (
        <t-space size="small">
          <span>{timeStr}</span>
          <t-tag theme={online ? "success" : "default"} size="small">
            {online ? "在线" : "离线"}
          </t-tag>
        </t-space>
      );
    },
  },
  { title: "启动", colKey: "enable", width: 100 },
  { title: "隐藏", colKey: "hidden", width: 100 },
];

// 在线判断：30 秒内有心跳视为在线，无心跳视为离线
const isOnline = (modifyTimeRaw: number) => {
  return modifyTimeRaw > 0 && Date.now() - modifyTimeRaw <= 30000;
};

// 归一化心跳时间戳：非法日期或无值返回 0
const toModifyTimeRaw = (modifyTime?: string): number => {
  if (!modifyTime) {
    return 0;
  }
  const ts = new Date(modifyTime).getTime();
  return Number.isFinite(ts) ? ts : 0;
};

const loadJudgers = async () => {
  if (!loadedOnce) {
    judgerLoading.value = true;
  }
  try {
    const res = await GetJudgerManageList();
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    // 请求返回后保留「正在更新」或「最近成功更新」的行，避免轮询旧快照覆盖乐观值
    const now = Date.now();
    const keepMap = new Map(
      judgerList.value
        .filter((r) => r.updating || (r.updatedAt !== undefined && now - r.updatedAt < 5000))
        .map((r) => [r.key, r]),
    );
    judgerList.value = (res.data || [])
      .map((j: Judger): JudgerRow => {
        const keep = keepMap.get(j.key);
        if (keep) {
          return keep;
        }
        return {
          key: j.key,
          name: j.name || "-",
          maxJob: j.max_job ? Number(j.max_job) : 0,
          modifyTimeRaw: toModifyTimeRaw(j.modify_time),
          enable: j.enable === true,
          hidden: j.hidden === true,
          updating: false,
        };
      })
      .sort((a: JudgerRow, b: JudgerRow) => a.key.localeCompare(b.key));
  } catch (e) {
    console.error(e);
    ShowErrorTips(globalProperties, "加载判题机列表失败");
  } finally {
    judgerLoading.value = false;
    loadedOnce = true;
  }
};

const handleToggleJudger = async (row: JudgerRow, field: "enable" | "hidden", value: boolean) => {
  const prev = row[field];
  row[field] = value; // 乐观更新，失败回滚
  row.updating = true;
  try {
    const res = await PostJudgerSetting(
      row.key,
      field === "enable" ? value : undefined,
      field === "hidden" ? value : undefined,
    );
    if (res.code !== 0) {
      row[field] = prev;
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    row.updatedAt = Date.now(); // 标记更新时间，轮询跳过该行避免旧快照覆盖乐观值
    ShowTextTipsInfo(globalProperties, field === "enable" ? "已更新判题机启动状态" : "已更新判题机隐藏状态");
  } catch (e) {
    console.error(e);
    row[field] = prev;
    ShowErrorTips(globalProperties, "更新判题机状态失败");
  } finally {
    row.updating = false;
  }
};

let refreshTimer: number | undefined;

onMounted(() => {
  loadJudgers();
  refreshTimer = window.setInterval(() => loadJudgers(), 5000);
});

onBeforeUnmount(() => {
  if (refreshTimer !== undefined) {
    clearInterval(refreshTimer);
  }
});

const searchForm = ref({
  problemKey: "",
  language: undefined as JudgeLanguage | undefined,
  status: undefined as JudgeStatus | undefined,
});

const rejudgeSearchLoading = ref(false);

// GetSubmitLanguages 返回的 value 允许 undefined（与其它页面保持一致）
const languageOptions = ref<{ label: string; value: JudgeLanguage | undefined }[]>([]);
languageOptions.value = GetSubmitLanguages();
const judgeStatusOptions = ref([] as { label: string; value: JudgeStatus }[]);
judgeStatusOptions.value = GetJudgeStatusOptions();

const handleRejudgeRecently = async () => {
  rejudgeRecentlyLoading.value = true;
  try {
    const res = await PostRejudgeRecently();
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsInfo(globalProperties, "重判成功");
    await router.push({ name: "judge-list" });
  } catch (e) {
    console.error(e);
    ShowErrorTips(globalProperties, "重判失败");
  } finally {
    rejudgeRecentlyLoading.value = false;
  }
};

const handleRejudgeSearch = async () => {
  if (!searchForm.value.problemKey && searchForm.value.language === undefined && searchForm.value.status === undefined) {
    ShowTextTipsError(globalProperties, "请输入问题标识");
    return;
  }
  rejudgeSearchLoading.value = true;
  try {
    const res = await PostRejudgeSearch(searchForm.value.problemKey, searchForm.value.language, searchForm.value.status);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsInfo(globalProperties, "重判成功");
    await router.push({
      name: "judge-list",
      query: {
        problem_key: searchForm.value.problemKey,
        language: searchForm.value.language,
      },
    });
  } catch (e) {
    console.error(e);
    ShowErrorTips(globalProperties, "重判失败");
  } finally {
    rejudgeSearchLoading.value = false;
  }
};

const handleRejudgeAll = async () => {
  rejudgeAllLoading.value = true;
  try {
    const res = await PostRejudgeAll();
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsInfo(globalProperties, "重判成功");
    await router.push({ name: "judge-list" });
  } catch (e) {
    console.error(e);
    ShowErrorTips(globalProperties, "重判失败");
  } finally {
    rejudgeAllLoading.value = false;
  }
};
</script>

<template>
  <t-card class="yj-manage-card" title="判题机管理">
    <t-table :data="judgerList" :columns="judgerColumns" row-key="key" :loading="judgerLoading" :bordered="true">
      <template #enable="{ row }">
        <t-popconfirm
          :content="'确定' + (row.enable ? '停用' : '启用') + '该判题机？停用后约 3 秒内停止接新任务'"
          @confirm="() => handleToggleJudger(row, 'enable', !row.enable)"
        >
          <t-switch :value="row.enable" />
        </t-popconfirm>
      </template>
      <template #hidden="{ row }">
        <t-switch :value="row.hidden" @change="(v: boolean) => handleToggleJudger(row, 'hidden', v)" />
      </template>
    </t-table>
    <div style="margin-top: 12px; color: #999; font-size: 12px">
      提示：停用后判题机约 3 秒内停止接新任务；隐藏后判题机将不在「系统状态」页显示，可在此重新显示。
    </div>
  </t-card>
  <t-card class="yj-manage-card" title="重判最近提交">
    <t-button :loading="rejudgeRecentlyLoading" @click="handleRejudgeRecently">重判</t-button>
  </t-card>
  <t-card class="yj-manage-card" title="重判指定记录">
    <t-form :layout="searchFormLayout" @submit="handleRejudgeSearch">
      <t-form-item label="问题标识">
        <t-input v-model="searchForm.problemKey" placeholder="请输入完整问题标识" />
      </t-form-item>
      <t-form-item label="语言">
        <t-select v-model="searchForm.language" placeholder="请选择提交语言" auto-width clearable>
          <t-option v-for="item in languageOptions" :key="item.value" :value="item.value" :label="item.label"></t-option>
        </t-select>
      </t-form-item>
      <t-form-item label="状态">
        <t-select v-model="searchForm.status" placeholder="请选择评测状态" auto-width clearable>
          <t-option v-for="item in judgeStatusOptions" :key="item.value" :value="item.value" :label="item.label"></t-option>
        </t-select>
      </t-form-item>
      <t-form-item>
        <t-space>
          <t-button theme="primary" type="submit" :loading="rejudgeSearchLoading">重判</t-button>
        </t-space>
      </t-form-item>
    </t-form>
  </t-card>
  <t-card class="yj-manage-card" title="重判所有">
    <t-button theme="danger" :loading="rejudgeAllLoading" @click="handleRejudgeAll">重判</t-button>
  </t-card>
</template>

<style scoped>
.yj-manage-card {
  margin: 20px;
}

@media (max-width: 800px) {
  .yj-manage-card {
    margin: 8px;
  }
}
</style>
